; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 1		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 1		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			ld (ntc_csp), sp
			ld a, (#BC77)		; Option RomEnable: start the ROMs again
			cp #DF			; AMSDOS has the cassette calls: they are running
			jp z, ntc_roms_on
			ei
			ld de, ntc_free		; the lowest address the ROMs may use (above the arrays)
			ld hl, #ABFF		; the highest (as usual for AMSDOS: it takes about #A700-#ABFF)
			ld c, 7
			call #BCCE		; KL INIT BACK: ROM 7 (DE / HL come back as the new limits)
			inc hl			; the first byte the ROMs took
			ld (ntc_roms_at), hl
			ld de, #A600
			or a
			sbc hl, de
			jp nc, ntc_roms_fit	; AMSDOS alone (or no more): as usual
			ld hl, (ntc_roms_at)
			ld de, -16
			add hl, de		; the event block under the ROMs' RAM: the new top
			ld (ntc_fwblk), hl
			ld (ntc_fwtop), hl
			ld de, ntc_free
			or a
			sbc hl, de
			jp nc, ntc_roms_fit	; the program still ends below it
			ld hl, ntc_roms_msg
			call ntc_roms_puts
			ld a, (ntc_roms_at + 1)
			call ntc_roms_hex
			ld a, (ntc_roms_at)
			call ntc_roms_hex
			ld hl, ntc_roms_msg2
			call ntc_roms_puts
			call #BB06		; KM WAIT CHAR
			rst 0			; (the machine starts again)
ntc_roms_puts:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_roms_puts
ntc_roms_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_roms_dig
			pop af
ntc_roms_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
ntc_roms_at:	dw 0
ntc_roms_msg:	db "The ROMs' RAM reaches down to #", 0
ntc_roms_msg2:	db ": no room for this program", 13, 10, "(fewer ROMs, or a smaller program)", 13, 10, "Press a key", 13, 10, 0
ntc_roms_fit:
			di
			ASSERT ntc_free <= #A600, "Option RomEnable: the program and its arrays must end below #A600 (the ROMs take their RAM from #ABFF down)"
ntc_roms_on:
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

			IF ($ < 32768) && (ntc_rg1_e - ntc_rg1 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
ntc_rg1:
; ============================================================
; Main Thread
; ============================================================

main_thread:

			; Main.bas 21: Print "Overlays on "; System.Platform; ", "; Memory.RamSize(); "K"
			dw fn_memory_ramsize, var_memory_ramsize_ramsize
			dw kw_printstrvar, str1
			dw kw_printint, var_memory_ramsize_ramsize
			dw kw_printstrvar, str2
			dw kw_printnl

			; Main.bas 23: Print "Level 1 loaded: "; Level1.Loaded()
			dw fn_level1_loaded, var_level1_loaded_loaded
			dw kw_printstrvar, str3
			dw kw_printint, var_level1_loaded_loaded
			dw kw_printnl

			; Main.bas 24: For lvl = 1 To 2
			dw kw_ltov, 1, var_lvl
for1_t:

			; Main.bas 25: If lvl = 1 Then score = score + Level1.Play(score)
			dw kw_cpeqvl, var_lvl, 1
			dw kw_goto_iffalse_n, if2_1
			dw p_level1_play_c, var_score
			dw kw_vtov, var_level1_play_play, tmp1
			dw kw_add, var_score, tmp1, var_score
if2_1:

			; Main.bas 26: If lvl = 2 Then score = score + Level2.Play(score)
			dw kw_cpeqvl, var_lvl, 2
			dw kw_goto_iffalse_n, if3_1
			dw p_level2_play_c, var_score
			dw kw_vtov, var_level2_play_play, tmp1
			dw kw_add, var_score, tmp1, var_score
if3_1:

			; Main.bas 27: Next
			dw kw_next1l_n, var_lvl, 2, for1_t
for1_e:

			; Main.bas 28: Print "Score "; score
			dw kw_printstrvar, str4
			dw kw_printint, var_score
			dw kw_printnl

			; Main.bas 30: Print "Free after level 1 "; Level1.LocalSize()
			dw fn_level1_localsize, var_level1_localsize_localsize
			dw kw_printstrvar, str5
			dw kw_printint, var_level1_localsize_localsize
			dw kw_printnl

			; Main.bas 31: Print "Free after level 2 "; Level2.LocalSize()
			dw fn_level2_localsize, var_level2_localsize_localsize
			dw kw_printstrvar, str6
			dw kw_printint, var_level2_localsize_localsize
			dw kw_printnl

			; Main.bas 32: Print "Heap, largest block "; Memory.Largest()
			dw fn_memory_largest, var_memory_largest_largest
			dw kw_printstrvar, str7
			dw kw_printint, var_memory_largest_largest
			dw kw_printnl

			; Main.bas 37: Print "Level 1 in page "; Level1.Page(); ", level 2 in page "; Level2.Page()
			dw fn_level1_page, var_level1_page_page
			dw kw_printstrvar, str8
			dw kw_printint, var_level1_page_page
			dw fn_level2_page, var_level2_page_page
			dw kw_printstrvar, str9
			dw kw_printint, var_level2_page_page
			dw kw_printnl

			; Main.bas 38: Print "Pages "; Memory.Map(1, Memory.Pages())
			dw fn_memory_pages, var_memory_pages_pages
			dw kw_vtov, var_memory_pages_pages, tmp1
			dw fn_memory_map, lit_1, tmp1, var_memory_map_map
			dw kw_printstrvar, str10
			dw kw_printstrvar, var_memory_map_map
			dw kw_printnl

			; Main.bas 39: Print "Unload level 1: "; Level1.Unload(); " - pages "; Memory.Map(1, Memory.Pages())
			dw fn_level1_unload, var_level1_unload_unload
			dw kw_printstrvar, str11
			dw kw_printint, var_level1_unload_unload
			dw kw_irq		; let interrupts in
			dw fn_memory_pages, var_memory_pages_pages
			dw kw_vtov, var_memory_pages_pages, tmp1
			dw fn_memory_map, lit_1, tmp1, var_memory_map_map
			dw kw_printstrvar, str12
			dw kw_printstrvar, var_memory_map_map
			dw kw_printnl

			; Main.bas 41: End
			dw kw_printnl0
			dw kw_printstrvar, str13
			dw kw_waitkey
			dw kw_stop

ntc_rg1_e:
			IF ($ < 32768) && (ntc_rg2_e - ntc_rg2 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
ntc_rg2:
; ============================================================
; sub banner (normal mode)
; ============================================================

p_banner:

			; Main.bas 45: Print "== "; text; " =="
			dw kw_printstrvar, str14
			dw kw_printstrvar, var_banner_text
			dw kw_printstrvar, str15
			dw kw_printnl
			dw p_banner_r

ntc_rg2_e:
			IF ($ < 32768) && (ntc_rg3_e - ntc_rg3 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
